134→func (d *Droid) Bootstrap() error {
135→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
136→	if apiKey != "" {
137→		home, err := os.UserHomeDir()
138→		if err != nil {
139→			return fmt.Errorf("get home dir: %w", err)
140→		}
141→		dir := filepath.Join(home, ".factory")
142→		if err := os.MkdirAll(dir, 0o755); err != nil {
143→			return fmt.Errorf("mkdir %s: %w", dir, err)
144→		}
145→
146→		settingsPath := filepath.Join(dir, "settings.json")
147→
148→		// Read existing settings to merge (hooks may already be configured
149→		// in the repo-local .factory/settings.json, but the global config
150→		// at ~/.factory/settings.json might have other pre-existing entries).
151→		var settings droidSettings
152→		if data, readErr := os.ReadFile(settingsPath); readErr == nil {
153→			// Best-effort merge: ignore parse errors and start fresh
154→			_ = json.Unmarshal(data, &settings)
155→		}
156→
157→		// Replace or add the BYOK model entry.
158→		byokModel := droidCustomModel{
159→			DisplayName:    droidCustomModelDisplayName,
160→			Model:          droidCustomModelBaseID,
161→			BaseURL:        "https://api.anthropic.com",
162→			APIKey:         apiKey,
163→			Provider:       "anthropic",
164→			MaxOutputToken: 8192,
165→		}
166→
167→		found := false
168→		for i, m := range settings.CustomModels {
169→			if m.Model == byokModel.Model {
170→				settings.CustomModels[i] = byokModel
171→				found = true
172→				break
173→			}
174→		}
175→		if !found {
176→			settings.CustomModels = append(settings.CustomModels, byokModel)
177→		}
178→
179→		// Set the BYOK model as the default for interactive mode.
180→		if settings.SessionDefaultSettings == nil {
181→			settings.SessionDefaultSettings = &droidSessionDefaults{}
182→		}
183→		settings.SessionDefaultSettings.Model = droidCustomModelBaseID
184→
185→		data, err := json.MarshalIndent(settings, "", "  ")
186→		if err != nil {
187→			return fmt.Errorf("marshal settings: %w", err)
188→		}
189→		if err := os.WriteFile(settingsPath, data, 0o644); err != nil {
190→			return fmt.Errorf("write settings: %w", err)
191→		}
192→	}
193→
194→	cfg := droidStartupConfigFromEnv()
195→	if !cfg.warmup {
196→		return nil
197→	}
198→	if err := d.warmup(); err != nil {
199→		fmt.Fprintf(os.Stderr, "droid warmup failed (non-fatal): %v\n", err)
200→	}
201→	return nil
202→}
