204→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
205→	cfg := &runConfig{Model: defaultDroidModel}
206→	for _, o := range opts {
207→		o(cfg)
208→	}
209→
210→	model := cfg.Model
211→	if model == "" {
212→		model = defaultDroidModel
213→	}
214→
215→	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
216→	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
217→
218→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
219→	cmd.Dir = dir
220→	cmd.Stdin = nil
221→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
222→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
223→	cmd.Cancel = func() error {
224→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
225→	}
226→	cmd.WaitDelay = 5 * time.Second
227→
228→	var stdout, stderr strings.Builder
229→	cmd.Stdout = &stdout
230→	cmd.Stderr = &stderr
231→
232→	err := cmd.Run()
233→	exitCode := 0
234→	if err != nil {
235→		exitErr := &exec.ExitError{}
236→		if errors.As(err, &exitErr) {
237→			exitCode = exitErr.ExitCode()
238→		} else {
239→			exitCode = -1
240→		}
241→	}
242→
243→	return Output{
244→		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
245→		Stdout:   stdout.String(),
246→		Stderr:   stderr.String(),
247→		ExitCode: exitCode,
248→	}, err
249→}
