287→func (d *Droid) warmup() error {
288→	const warmupAttempts = 2
289→	const warmupTimeout = 30 * time.Second
290→
291→	dir, err := os.MkdirTemp("", "droid-warmup-*")
292→	if err != nil {
293→		return fmt.Errorf("create warmup dir: %w", err)
294→	}
295→	defer func() { _ = os.RemoveAll(dir) }()
296→
297→	var lastErr error
298→	for attempt := range warmupAttempts {
299→		ctx, cancel := context.WithTimeout(context.Background(), warmupTimeout)
300→		out, err := d.RunPrompt(ctx, dir, "Reply with OK.", WithModel(defaultDroidModel))
301→		cancel()
302→		if err == nil {
303→			return nil
304→		}
305→
306→		lastErr = fmt.Errorf("%w (stderr: %s)", err, strings.TrimSpace(out.Stderr))
307→		if attempt < warmupAttempts-1 && d.IsTransientError(out, err) {
308→			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
309→			continue
310→		}
311→		break
312→	}
313→	return lastErr
314→}
